namespace CheckoutPricing.Domain;

public enum LoyaltyTier
{
    Bronze,
    Silver,
    Gold
}
E
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int DiscountCeilingPoints = 10;

    public int For(LoyaltyTier tier, int subtotalCents)
    {
        var baseRate = tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 7,
            LoyaltyTier.Gold => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, "Unapproved loyalty tier.")
        };

        var bonus = subtotalCents switch
        {
            >= 20000 => 3,
            >= 5000 => 1,
            _ => 0
        };

        var rate = Math.Min(baseRate + bonus, DiscountCeilingPoints);
        var discount = (int)((long)subtotalCents * rate / 100);

        return subtotalCents - discount;
    }
}
E
python3 - <<'E'
p='tests/CheckoutPricing.UnitTests/LoyaltyDiscountTests.cs'
s=open(p).read()
s=s.replace("using CheckoutPricing.Application;","using CheckoutPricing.Application;\nusing CheckoutPricing.Domain;")
s=s.replace("string tier,","LoyaltyTier tier,")
import re
s=re.sub(r'InlineData\("(\w+)"',r'InlineData(LoyaltyTier.\1',s)
s=s.replace("For(subtotalCents)","For(tier, subtotalCents)")
open(p,'w').write(s)
E
dotnet test 2>&1 | grep -E "error|expected payable|Passed!|Failed!"

